def f(text):
 counts={'a':0}
 original=counts
 try:
  for counts in text.lower().split():
   counts[counts]=counts.get(counts,0)+1
 except AttributeError:print(original,counts)
 else:print('wrong',original,counts)
f('a a')
def f(text):
 counts={'a':0}
 word=0
 try:
  for word in text.lower().split():
   counts[word]=counts.get(word,0)+1
   word+=1
 except TypeError:print(counts,word)
 else:print('wrong',counts,word)
f('a a')
